#include <iostream>
#include <iomanip>

int main() {
    int total{0};
    int count{0};

    if (std::cin >> total >> count && count > 0) {
        // static_cast performs explicit conversion
        // count is implicitly promoted to double
        double average = static_cast<double>(total) / count;

        std::cout << "Default: " << average << "\n";
        std::cout << "Fixed 2 decimals: " << std::fixed << std::setprecision(2) << average << "\n";
    }
    return 0;
}

#include <iostream>

int main() {
    // Phase 1: Initialization
    int passes{0};
    int failures{0};
    int studentCounter{1};

    // Phase 2: Processing with nested if...else inside while
    while (studentCounter <= 10) {
        int result{0};
        if (std::cin >> result) {
            if (result == 1) {
                passes = passes + 1;
            } else {
                failures = failures + 1;
            }
            studentCounter = studentCounter + 1;
        } else {
            break;
        }
    }

    // Phase 3: Reporting and decision
    std::cout << "Passed: " << passes << "\n";
    std::cout << "Failed: " << failures << "\n";

    if (passes > 8) {
        std::cout << "Bonus to instructor!\n";
    }

    return 0;
}
